/*
 * @lc app=leetcode id=3448 lang=java
 *
 * [3448] Count Substrings Divisible By Last Digit
 */
class Solution { fun countSubstrings(s: String): Long = arrayOf(LongArray(4), LongArray(3), LongArray(9), Array(6) { LongArray(7) }, IntArray(1)).let { st -> s.indices.forEach { j -> ((st[4] as IntArray).also { it[0] = s[j] - '0' }).run { (st[0] as LongArray).also { it[1] = (it[1] * 10 + (st[4] as IntArray)[0]) % 3 }.also { it[2] = (it[2] * 10 + (st[4] as IntArray)[0]) % 7 }.also { it[3] = (it[3] * 10 + (st[4] as IntArray)[0]) % 9 }.also { it[0] += (st[4] as IntArray)[0].let { d -> if (d == 0) 0L else if (d == 1 || d == 2 || d == 5) (j + 1L) else if (d == 4) (if (j == 0) 1L else if (((s[j - 1] - '0') * 10 + d) % 4 == 0) (j + 1L) else 1L) else if (d == 8) (if (j == 0) 1L else if (j == 1) (if (((s[0] - '0') * 10 + 8) % 8 == 0) 2L else 1L) else (if (((s[j - 2] - '0') * 100 + (s[j - 1] - '0') * 10 + 8) % 8 == 0) j - 1L else 0L) + (if (((s[j - 1] - '0') * 10 + 8) % 8 == 0) 1L else 0L) + 1L) else if (d == 3 || d == 6) ((if ((st[0] as LongArray)[1] == 0L) 1L else 0L) + (st[1] as LongArray)[(st[0] as LongArray)[1].toInt()]) else if (d == 9) ((if ((st[0] as LongArray)[3] == 0L) 1L else 0L) + (st[2] as LongArray)[(st[0] as LongArray)[3].toInt()]) else if (d == 7) ((if ((st[0] as LongArray)[2] == 0L) 1L else 0L) + (st[3] as Array<LongArray>)[j % 6][((st[0] as LongArray)[2] * 1 % 7).toInt()] + (st[3] as Array<LongArray>)[(j % 6 + 5) % 6][((st[0] as LongArray)[2] * 5 % 7).toInt()] + (st[3] as Array<LongArray>)[(j % 6 + 4) % 6][((st[0] as LongArray)[2] * 4 % 7).toInt()] + (st[3] as Array<LongArray>)[(j % 6 + 3) % 6][((st[0] as LongArray)[2] * 6 % 7).toInt()] + (st[3] as Array<LongArray>)[(j % 6 + 2) % 6][((st[0] as LongArray)[2] * 2 % 7).toInt()] + (st[3] as Array<LongArray>)[(j % 6 + 1) % 6][((st[0] as LongArray)[2] * 3 % 7).toInt()]) else 0L } } }.run { (st[1] as LongArray)[(st[0] as LongArray)[1].toInt()]++ }.run { (st[3] as Array<LongArray>)[j % 6][(st[0] as LongArray)[2].toInt()]++ }.run { (st[2] as LongArray)[(st[0] as LongArray)[3].toInt()]++ } }.run { (st[0] as LongArray)[0] } } }